-- Recipe ids are short random strings generated by the database (names collide; "evil" won't stay unique).
-- 8 chars from an alphabet without look-alikes (no 0/o, 1/l/i): ~1e12 ids.
create or replace function public.gen_recipe_id() returns text
language plpgsql volatile as $$
declare
  a constant text := 'abcdefghjkmnpqrstuvwxyz23456789';
  candidate text;
begin
  loop
    candidate := '';
    for i in 1..8 loop
      candidate := candidate || substr(a, 1 + floor(random() * length(a))::int, 1);
    end loop;
    exit when not exists (select 1 from public.recipes r where r.id = candidate);
  end loop;
  return candidate;
end $$;

alter table public.recipes alter column id set default public.gen_recipe_id();

-- site submissions always get a generated id; the repo sync (backend) keeps the id from the file
create or replace function public.recipes_assign_id() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if not public.is_backend() or new.id is null or new.id = '' then
    new.id := public.gen_recipe_id();
  end if;
  return new;
end $$;

drop trigger if exists recipes_aaa_id on public.recipes;
create trigger recipes_aaa_id before insert on public.recipes for each row execute function public.recipes_assign_id();

update public.recipes set id = 'cyuwrb3w' where id = 'evil';
